<script setup>
import { ESPERA_FILTROS_MS } from '@/Utils/filtroUtil'
import { ref, watch, computed, onMounted } from 'vue'
import { Head, Link, router, usePage, InfiniteScroll } from '@inertiajs/vue3'
import Maindashboard from '@/Layouts/Maindashboard.vue'
defineOptions({ layout: Maindashboard })
import { showToast, confirm } from '@/Utils/alertUtil.js'
import { useBootstrapModal } from '@/Composables/useBootstrapModal'
import { useBreakpoints, breakpointsTailwind } from '@vueuse/core'

const page = usePage()

const props = defineProps({
    solicitudes: Object,
    vehiculos: Array,
    filters: Object,
    flash: Object,
})

// Debajo de "lg" (tablet en portrait y celular) se muestra un segundo
// listado en tarjetas con scroll infinito en vez de la tabla (ver
// .ai/rules/pages.md, "Listado responsivo con scroll infinito").
const breakpoints = useBreakpoints(breakpointsTailwind)
const isMobile = breakpoints.smaller('lg')

const filters = ref({
    estado: props.filters?.estado ?? '',
    tipo_mantenimiento: props.filters?.tipo_mantenimiento ?? '',
    id_vehiculo: props.filters?.id_vehiculo ?? '',
})

// Modal de solicitudes pendientes
const showPendingModal = ref(false)
const modal = useBootstrapModal()
const modalKey = 'pendingModalShown'

// Verificar si el usuario es conductor
const esUsuarioConductor = computed(() => {
    const roles = page.props.auth?.roles || []
    return roles.includes('conductor')
})

// Obtener solicitudes pendientes
const solicitudesPendientes = computed(() => {
    return props.solicitudes?.data?.filter(s => s.estado === 'PENDIENTE') || []
})

// Verificar si debe mostrarse el modal
const verificarYMostrarModal = () => {
    // No mostrar si es conductor
    if (esUsuarioConductor.value) {
        return
    }

    // const yaVisto = sessionStorage.getItem(modalKey)
    if ( solicitudesPendientes.value.length > 0) {
        showPendingModal.value = true
        sessionStorage.setItem(modalKey, 'true')
        // Mostrar modal cuando el DOM esté listo
        setTimeout(() => {
            const modalEl = document.getElementById('pendingRequestsModal')
            if (modalEl) {
                modal.mostrar(modalEl)
            }
        }, 300)
    }
}

// Watch de cambios en solicitudes (detecta nuevo login)
watch(() => props.solicitudes?.data?.length, () => {
    verificarYMostrarModal()
})

// Inicializar al montar
onMounted(() => {
    verificarYMostrarModal()
})

// Cerrar modal
const cerrarModalPendiente = () => {
    modal.ocultar()
    showPendingModal.value = false
}

let debounceTimer = null
watch(filters, (val) => {
    clearTimeout(debounceTimer)
    debounceTimer = setTimeout(() => {
        router.get(route('mantenimiento.solicitudes.index'), {
            estado: val.estado || undefined,
            tipo_mantenimiento: val.tipo_mantenimiento || undefined,
            id_vehiculo: val.id_vehiculo || undefined,
        }, { preserveState: true, replace: true })
    }, ESPERA_FILTROS_MS)
}, { deep: true })

function clearFilters() {
    filters.value = { estado: '', tipo_mantenimiento: '', id_vehiculo: '' }
}

const estadoBadge = (estado) => {
    const map = {
        PENDIENTE: 'bg-warning-transparent text-warning',
        APROBADA:  'bg-success-transparent text-success',
        RECHAZADA: 'bg-danger-transparent text-danger',
        ANULADA:   'bg-secondary-transparent text-secondary',
    }
    return map[estado] ?? 'bg-light text-dark'
}

const tipoBadge = (tipo) => {
    return tipo === 'PREVENTIVO'
        ? 'bg-info-transparent text-info'
        : 'bg-danger-transparent text-danger'
}
</script>

<template>
    <Head title="Solicitudes de Mantenimiento" />
        <!-- Breadcrumb -->
        <div class="d-flex align-items-center justify-content-between page-header-breadcrumb flex-wrap gap-2 mb-4">
            <div>
                <nav>
                    <ol class="breadcrumb mb-1">
                        <li class="breadcrumb-item"><Link :href="route('dashboard')">Inicio</Link></li>
                        <li class="breadcrumb-item active">Solicitudes de Mantenimiento</li>
                    </ol>
                </nav>
                <h1 class="page-title fw-medium fs-18 mb-0">Solicitudes de Mantenimiento</h1>
            </div>
            <Link v-can="'mantenimiento.solicitudes.crear'" :href="route('mantenimiento.solicitudes.create')"
                class="btn btn-primary btn-wave">
                <i class="ri-add-line me-1"></i> Nueva Solicitud
            </Link>
        </div>

        <!-- Flash -->
        <div v-if="flash?.success" class="alert alert-success alert-dismissible fade show" role="alert">
            <i class="ri-checkbox-circle-line me-2"></i>{{ flash.success }}
            <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
        </div>
        <div v-if="flash?.error" class="alert alert-danger alert-dismissible fade show" role="alert">
            <i class="ri-error-warning-line me-2"></i>{{ flash.error }}
            <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
        </div>

        <!-- Modal de Solicitudes Pendientes -->
        <div id="pendingRequestsModal" class="modal fade" tabindex="-1" role="dialog" aria-hidden="true">
            <div class="modal-dialog modal-dialog-centered modal-lg" role="document">
                <div class="modal-content border-warning">
                    <div class="modal-header bg-warning bg-opacity-10 border-warning">
                        <div>
                            <h5 class="modal-title fw-bold text-warning">
                                <i class="ri-alert-line me-2"></i>Solicitudes Pendientes
                            </h5>
                            <small class="text-muted">Tienes {{ solicitudesPendientes.length }} solicitud(es) pendiente(s) de aprobación</small>
                        </div>
                        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                    </div>
                    <div class="modal-body">
                        <div class="table-responsive">
                            <table class="table table-hover table-sm mb-0">
                                <thead class="table-light">
                                    <tr>
                                        <th>Nro</th>
                                        <th>Fecha</th>
                                        <th>Vehículo</th>
                                        <th>Tipo</th>
                                        <th>Descripción</th>
                                        <th class="text-center">Ver</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-for="s in solicitudesPendientes" :key="s.id" class="align-middle">
                                        <td class="fw-medium">{{ s.nro }}</td>
                                        <td><small>{{ s.fecha }}</small></td>
                                        <td>
                                            <span class="fw-medium">{{ s.vehiculo?.codigo ?? '—' }} – {{ s.vehiculo?.nro_placa ?? '—' }}</span>
                                            <br /><small class="text-muted">{{ s.vehiculo?.marca ?? '' }}</small>
                                        </td>
                                        <td>
                                            <span class="badge" :class="tipoBadge(s.tipo_mantenimiento)">
                                                {{ s.tipo_mantenimiento }}
                                            </span>
                                        </td>
                                        <td style="max-width:200px;white-space:normal;">
                                            <small>{{ s.descripcion_problema?.substring(0, 60) }}{{ s.descripcion_problema?.length > 60 ? '…' : '' }}</small>
                                        </td>
                                        <td class="text-center">
                                            <Link :href="route('mantenimiento.solicitudes.show', s.id)"
                                                class="btn btn-sm btn-outline-primary btn-wave">
                                                <i class="ri-eye-line"></i>
                                            </Link>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                    </div>
                    <div class="modal-footer bg-light">
                        <button type="button" class="btn btn-primary btn-wave fw-medium" data-bs-dismiss="modal" @click="cerrarModalPendiente">
                            <i class="ri-check-line me-1"></i>De acuerdo
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Filtros -->
        <div class="card custom-card mb-4">
            <div class="card-header"><div class="card-title">Filtros</div></div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-sm-6 col-xl-4">
                        <label class="form-label">Estado</label>
                        <select v-model="filters.estado" class="form-select">
                            <option value="">Todos</option>
                            <option value="PENDIENTE">Pendiente</option>
                            <option value="APROBADA">Aprobada</option>
                            <option value="RECHAZADA">Rechazada</option>
                            <option value="ANULADA">Anulada</option>
                        </select>
                    </div>
                    <div class="col-sm-6 col-xl-4">
                        <label class="form-label">Tipo</label>
                        <select v-model="filters.tipo_mantenimiento" class="form-select">
                            <option value="">Todos</option>
                            <option value="PREVENTIVO">Preventivo</option>
                            <option value="CORRECTIVO">Correctivo</option>
                        </select>
                    </div>
                    <div class="col-sm-6 col-xl-4">
                        <label class="form-label">Vehículo</label>
                        <select v-model="filters.id_vehiculo" class="form-select">
                            <option value="">Todos</option>
                            <option v-for="v in vehiculos" :key="v.id" :value="v.id">
                                {{ v.codigo }} – {{ v.nro_placa }} – {{ v.marca }}
                            </option>
                        </select>
                    </div>
                </div>
                <div class="mt-3 d-flex justify-content-end">
                    <button type="button" class="btn btn-outline-secondary btn-wave" @click="clearFilters">
                        <i class="ri-refresh-line me-1"></i> Limpiar
                    </button>
                </div>
            </div>
        </div>

        <!-- Tabla -->
        <div class="card custom-card">
            <div class="card-header d-flex align-items-center justify-content-between">
                <div class="card-title">
                    Solicitudes
                    <span class="badge bg-primary-transparent text-primary ms-2">{{ solicitudes.total }} registros</span>
                </div>
            </div>
            <!-- Vista tabla: desktop -->
            <div v-if="!isMobile" class="card-body p-0">
                <div class="table-responsive">
                    <table class="table table-hover align-middle mb-0">
                        <thead class="table-light">
                            <tr>
                                <th>#</th>
                                <th>Nro</th>
                                <th>Fecha</th>
                                <th>Vehículo</th>
                                <th>Conductor</th>
                                <th>Tipo</th>
                                <th>Descripción</th>
                                <th>Km actual</th>
                                <th>Estado</th>
                                <th class="text-center">Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-if="solicitudes.data.length === 0">
                                <td colspan="9" class="text-center py-4 text-muted">
                                    <i class="ri-tools-line fs-3 d-block mb-2"></i>
                                    No se encontraron solicitudes
                                </td>
                            </tr>
                            <tr v-for="(s, idx) in solicitudes.data" :key="s.id">
                                <td>{{ idx + 1 }}</td>
                                <td>{{ s.nro }}</td>
                                <td>{{ s.fecha }}</td>
                                <td>
                                    <span class="fw-medium">{{ s.vehiculo?.codigo ?? '—' }} – {{ s.vehiculo?.nro_placa ?? '—' }}</span>
                                    <br /><small class="text-muted">{{ s.vehiculo?.marca ?? '' }}</small>
                                </td>
                                <td>{{ s.conductor ? `${s.conductor.persona.nombre_completo}` : '—' }}</td>
                                <td><span class="badge" :class="tipoBadge(s.tipo_mantenimiento)">{{ s.tipo_mantenimiento }}</span></td>
                                <td style="max-width:220px;white-space:normal;">
                                    {{ s.descripcion_problema?.substring(0, 80) }}{{ s.descripcion_problema?.length > 80 ? '…' : '' }}
                                </td>
                                <td>{{ s.kilometraje_actual != null ? s.kilometraje_actual.toLocaleString() + ' km' : '—' }}</td>
                                <td><span class="badge" :class="estadoBadge(s.estado)">{{ s.estado }}</span></td>
                                <td class="text-center">
                                    <div class="btn-group btn-group-sm">
                                        <Link :href="route('mantenimiento.solicitudes.show', s.id)"
                                            class="btn btn-outline-primary btn-wave" title="Ver detalle">
                                            <i class="ri-eye-line"></i>
                                        </Link>
                                        <Link v-can="'mantenimiento.solicitudes.imprimir'" :href="route('mantenimiento.solicitudes.imprimir', s.id)" target="_blank"
                                            class="btn btn-outline-primary btn-wave" title="Ver detalle">
                                            <i class="ri-file-list-3-line"></i>
                                        </Link>
                                        <!-- <Link v-if="s.estado === 'PENDIENTE' && !s.orden_trabajo" -->
                                         <Link v-if="false" >
                                            :href="route('mantenimiento.ordenes.create', { solicitud: s.id })"
                                            class="btn btn-outline-success btn-wave" title="Generar orden de trabajo">
                                            <i class="ri-file-list-3-line"></i>
                                        </Link>
                                    </div>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <!-- Vista tarjetas: tablet y celular, con scroll infinito -->
            <div v-else class="card-body p-2">
                <div v-if="solicitudes.data.length === 0" class="text-center py-4 text-muted">
                    <i class="ri-tools-line fs-3 d-block mb-2"></i>
                    No se encontraron solicitudes
                </div>

                <InfiniteScroll v-else data="solicitudes" only-next as="div" class="d-flex flex-column gap-2">
                    <div v-for="s in solicitudes.data" :key="s.id" class="list-card-mobile border rounded-3 p-3"
                        @click="router.get(route('mantenimiento.solicitudes.show', s.id))">

                        <div class="d-flex align-items-center justify-content-between mb-2">
                            <span class="badge bg-primary fs-13 fw-semibold">{{ s.nro }}</span>
                            <span class="badge" :class="estadoBadge(s.estado)">{{ s.estado }}</span>
                        </div>

                        <div class="mb-2">
                            <span class="fw-semibold d-block">{{ s.vehiculo?.codigo ?? '—' }} – {{ s.vehiculo?.nro_placa ?? '—' }}</span>
                            <small v-if="s.vehiculo?.marca" class="text-muted">{{ s.vehiculo.marca }}</small>
                        </div>

                        <p class="small text-muted mb-2">
                            {{ s.descripcion_problema?.substring(0, 100) }}{{ s.descripcion_problema?.length > 100 ? '…' : '' }}
                        </p>

                        <div class="row g-2 small mb-2">
                            <div class="col-6">
                                <span class="text-muted d-block">Conductor</span>
                                <span>{{ s.conductor ? `${s.conductor.persona.nombre_completo}` : '—' }}</span>
                            </div>
                            <div class="col-6">
                                <span class="text-muted d-block">Tipo</span>
                                <span class="badge" :class="tipoBadge(s.tipo_mantenimiento)">{{ s.tipo_mantenimiento }}</span>
                            </div>
                            <div class="col-6">
                                <span class="text-muted d-block">Fecha</span>
                                <span>{{ s.fecha }}</span>
                            </div>
                            <div class="col-6">
                                <span class="text-muted d-block">Km actual</span>
                                <span>{{ s.kilometraje_actual != null ? s.kilometraje_actual.toLocaleString() + ' km' : '—' }}</span>
                            </div>
                        </div>

                        <div class="d-flex align-items-center justify-content-end gap-1 border-top pt-2" @click.stop>
                            <Link v-can="'mantenimiento.solicitudes.imprimir'" :href="route('mantenimiento.solicitudes.imprimir', s.id)"
                                target="_blank" class="btn btn-icon btn-light" title="Imprimir">
                                <i class="ri-file-list-3-line"></i>
                            </Link>
                        </div>
                    </div>

                    <!-- Indicador de carga / fin de lista del scroll infinito -->
                    <template #next="{ loading, hasMore }">
                        <div v-if="loading" class="text-center text-muted small py-2">
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            Cargando más solicitudes...
                        </div>
                        <div v-else-if="!hasMore" class="text-center text-muted small py-2">
                            No hay más solicitudes para mostrar.
                        </div>
                    </template>
                </InfiniteScroll>
            </div>

            <!-- Paginación: sólo la tabla desktop. El listado mobile usa
                 scroll infinito (InfiniteScroll arriba) en vez de páginas
                 numeradas. -->
            <div v-if="!isMobile && solicitudes.last_page > 1" class="card-footer d-flex justify-content-between align-items-center">
                <small class="text-muted">
                    Mostrando {{ solicitudes.from }}–{{ solicitudes.to }} de {{ solicitudes.total }}
                </small>
                <nav>
                    <ul class="pagination pagination-sm mb-0">
                        <li class="page-item" :class="{ disabled: !solicitudes.prev_page_url }">
                            <Link class="page-link" :href="solicitudes.prev_page_url ?? '#'">‹</Link>
                        </li>
                        <li v-for="page in solicitudes.last_page" :key="page" class="page-item"
                            :class="{ active: page === solicitudes.current_page }">
                            <Link class="page-link"
                                :href="route('mantenimiento.solicitudes.index', { page })">{{ page }}</Link>
                        </li>
                        <li class="page-item" :class="{ disabled: !solicitudes.next_page_url }">
                            <Link class="page-link" :href="solicitudes.next_page_url ?? '#'">›</Link>
                        </li>
                    </ul>
                </nav>
            </div>
        </div>
</template>
